const experimentModes={particles:['Celsius temperature',-50,100,20,'°C'],thermometer:['Displayed reading R',4,109,46,'°C'],insulation:['Water mass',100,500,100,'g'],heatcurve:['Energy into ice at 0°C',0,100.2,25.05,'kJ'],transfer:['Radiation emitted',0,100,70,'W'],fridge:['Energy removed from cold region',0,1200,600,'J'],journey:['Westward return distance',0,120,50,'m'],components:['Angle north of east',0,90,30,'°'],subtraction:['Final northward velocity',0,12,5,'m/s']};
function exploration(k){const [label,min,max,value,unit]=experimentModes[k];return '<div class="pp-sim" data-tv-experiment="'+k+'"><label>'+esc(label)+' <input type="range" data-tv-range min="'+min+'" max="'+max+'" step="'+(k==='heatcurve'?.25:1)+'" value="'+value+'"><output data-tv-label>'+value+' '+unit+'</output></label><p>Predict the outcome, move the control, then explain the changing quantity.</p><div class="pp-sim-readout" data-tv-result>'+experimentResult(k,value)+'</div><p class="pp-caption">A simplified calculated model. Fixed conditions are stated in the readout.</p></div>';}
function experimentResult(k,x){const f=n=>Number(n).toFixed(2);switch(k){case'particles':return 'T = '+f(x+273.15)+' K. This converts absolute temperature; it does not add an offset to a temperature rise.';case'thermometer':return 'Calibration R = 1.05T + 4.00 → true T = '+f((x-4)/1.05)+'°C. Offset and scale factor are fixed.';case'insulation':return 'Fixed 840 J energy loss, water c = 4200 J/(kg K): temperature-drop magnitude = '+f(840/(x/1000*4200))+' K. Only mass changes; transfer energy is fixed.';case'heatcurve':return 'Initial 0.300 kg ice at 0°C, L = 334 kJ/kg: melted '+f(x/334*1000)+' g, '+f(x/100.2*100)+'%. Both phases coexist below 100% melting; temperature stays 0°C.';case'transfer':return 'Fixed absorption 25 W: net outward radiation = '+f(x-25)+' W. A negative result means net absorption, despite simultaneous emission.';case'fridge':return 'Fixed electrical input 200 J: rejected room-side energy = '+f(x+200)+' J. Removed energy and input work add.';case'journey':return 'First travel 120 m east; return '+x+' m west; total time fixed at 85 s. Distance = '+f(120+x)+' m; displacement = '+f(120-x)+' m east. Average speed = '+f((120+x)/85)+' m/s; average velocity = '+f((120-x)/85)+' m/s east.';case'components':return 'Fixed vector 10.0 N; x east = '+f(10*Math.cos(x*Math.PI/180))+' N; y north = '+f(10*Math.sin(x*Math.PI/180))+' N. Check 0° and 90° to see which component is adjacent.';case'subtraction':return 'Initial (12,0) m/s; final (0,'+x+') m/s. Δv = (−12,'+x+') m/s; magnitude '+f(Math.hypot(12,x))+' m/s. Average acceleration over 2 s has magnitude '+f(Math.hypot(12,x)/2)+' m/s².';}}
document.addEventListener('input',e=>{if(!e.target.matches?.('[data-tv-range]'))return;const root=e.target.closest('[data-tv-experiment]'),k=root.dataset.tvExperiment,x=Number(e.target.value);root.querySelector('[data-tv-label]').textContent=x+' '+experimentModes[k][4];root.querySelector('[data-tv-result]').textContent=experimentResult(k,x);});

const diagnoses={particles:'Temperature establishes thermal state and net transfer direction, while internal energy depends on amount, material and phase. A cup and tank at 50°C have equal temperature but different energy stores.',thermometer:'Resolution describes displayed steps. Accuracy also depends on calibration, lag and placement. A highly resolved sensor with a +2°C offset remains systematically shifted until corrected.',insulation:'Insulation reduces transfer rather than supplying energy. It slows outward transfer from a warm person and inward transfer to cold ice, so either can remain closer to its starting state for longer.',heatcurve:'Energy at a phase-change plateau changes particle arrangement and phase proportions. Ice can absorb 25.05 kJ and partially melt at 0°C; only surplus energy after complete melting warms liquid.',transfer:'Natural convection can make warm fluid rise because of density and buoyancy. Conduction and radiation can transfer in other directions, so heat does not always travel upwards.',fridge:'A refrigerator moves energy from the cold compartment and adds electrical work. Removing 600 J while taking 200 J work rejects 800 J to the room; conservation is maintained.',journey:'Average speed uses distance while average velocity uses displacement. Travelling 120 m east then 50 m west gives 170 m distance but only 70 m east displacement, yielding different averages over the same time.',components:'Vector sums depend on direction. Two perpendicular equal forces add by Pythagoras; opposite equal forces cancel. Resolve and add signed components before reconstructing magnitude.',subtraction:'Velocity includes direction. A turn or rebound can change velocity with unchanged speed, producing nonzero acceleration. Final minus initial must use the complete vectors.'};
function marking(q){return '<table class="pf-marking"><thead><tr><th>Expected reasoning and working</th><th>Marks</th></tr></thead><tbody>'+q.points.map(p=>'<tr><td>'+esc(p)+'</td><td>1</td></tr>').join('')+'</tbody></table>';}
function task(q){return note('Original exam-style question',q.points.length+' marks. Read, draw and explain before checking.')+P(q.q)+paper('Your diagram, model, equations and explained working')+reveal('Review the explained marking guide',marking(q));}
const claims={particles:'Equal temperatures always imply equal internal energies.',thermometer:'More display digits guarantee a more accurate temperature.',insulation:'Insulation supplies energy to make every wrapped object warmer.',heatcurve:'Every joule from a heater immediately increases temperature.',transfer:'Heat always rises, so energy cannot transfer downwards.',fridge:'A refrigerator destroys the energy removed from food.',journey:'Average speed and average velocity are always equal.',components:'Two force magnitudes can always be added without considering direction.',subtraction:'If speed is unchanged, velocity and acceleration must be unchanged.'};
