 d.guided.forEach((g,i)=>pages.push({chapter:3,title:'Guided calculation '+(i+1)+': try before checking',html:'<div class="pp-page">'+number(d.id+'-guided-'+i,g[0],g[1],g[2],g[3],Math.max(Math.abs(g[1])*.003,.002))+'</div>',type:'practice'}));
 d.practice.forEach((q,i)=>pages.push({chapter:3,title:'Independent exam-style problem '+(i+1),html:'<div class="pp-page">'+task(q)+'</div>',type:'practice'}));
 pages.push({chapter:3,title:'Diagnose a plausible but incorrect claim',html:'<div class="pp-page">'+P('A student claims: “'+claims[d.diagram]+'”')+paper('Identify the error, supply the correct model, and use one specific example from this lesson.')+reveal('Build a stronger answer',P(diagnoses[d.diagram]))+'</div>',type:'practice'});
 pages.push({chapter:3,title:'Retrieval: explain without looking back',html:'<div class="pp-page">'+P('Close the preceding explanations and answer: '+d.bank[0].q)+check(d.id+'-retrieve',d.bank[0].q,d.bank[0].o,d.bank[0].a,d.bank[0].o.map((_,i)=>(i===d.bank[0].a?'Correct. ':'Review the model. ')+d.bank[0].explain))+paper('Write a reason, not just an option letter.')+'</div>',type:'practice'});
 pages.push({chapter:3,title:'Compare two cases and choose the model',html:'<div class="pp-page">'+P('Compare the two independent problems. Explain which quantities, directions or initial states differ and which relationships remain valid.')+paper('For each problem: knowns → requested quantity → model → first step → limitation')+reveal('Check your comparison',P(d.practice[0].points[0])+P(d.practice[1].points[0])+P('These are the first model decisions. Reproduce the remaining working and identify why the two solutions do not simply use identical numerical substitution.'))+'</div>',type:'practice'});
 pages.push({chapter:3,title:'Your concise reference and next attempt',html:'<div class="pp-page">'+P(d.sections[23][1])+note('Ready for the concept check?','Explain the labelled model, solve both written questions without the guide, and check quantities, units, direction and assumptions. If a step is uncertain, revisit that section before trying the mastery questions.')+'</div>',type:'learn'});
 const spec={id:d.id,parent:d.parent,title:d.title,shortTitle:d.shortTitle,subtitle:d.subtitle,pages,bank:d.bank,practice:d.practice,chapters:[['Recognise','Name the quantities and build the physical picture'],['Build','Connect definitions, mechanisms and relationships'],['Solve','Follow complete explained worked examples'],['Practise','Try, diagnose, compare and transfer']],constants:'Use SI units and stated constants. Keep extra digits until final reporting. Thermal examples specify simplified conditions; vector examples use ordinary low-speed mechanics. All questions are original exam-style practice.',focus:{title:d.title,question:d.practice[0].q,points:d.practice[0].points,claim:claims[d.diagram]},summary:d.subtitle};
